from gen import *
E=[]
def lrow(i,t,s=""): return f'<div class="row" style="padding:14px 0;border-top:1px solid var(--line)"><div style="display:flex;gap:14px;align-items:center"><span class="ico" style="width:40px;height:40px">{ic(i,18)}</span><div><b style="font-size:15px">{t}</b>{("<div class=sub style=margin-top:2px>"+s+"</div>") if s else ""}</div></div><span class="mut">›</span></div>'
def trow(t,s,on=True): return f'<div class="row" style="padding:14px 0;border-top:1px solid var(--line)"><div><b style="font-size:15px">{t}</b><div class="sub" style="margin-top:2px">{s}</div></div><span style="width:46px;height:28px;border-radius:99px;background:{"var(--ink)" if on else "#D9D9D2"};position:relative;display:block"><i style="position:absolute;top:3px;{"right" if on else "left"}:3px;width:22px;height:22px;border-radius:50%;background:{"var(--lime)" if on else "#fff"}"></i></span></div>'
E.append(phone("E1 · ACCOUNT", pad('<div class="h1" style="font-size:26px;margin-top:8px">Account</div><div class="row" style="margin:18px 0"><div style="display:flex;gap:14px;align-items:center"><span class="logo" style="background:var(--ink);width:56px;height:56px;font-size:18px">AM</span><div><b style="font-size:18px">Aarav Mehta</b><div class="sub">Client ID CR204817</div></div></div>'+pill("KYC done","up")+'</div>'+lrow("user","View profile","Personal details, nominee, bank")+lrow("bank","Funds","Add money and withdraw")+lrow("doc","Reports","Contract notes, statements, tax")+lrow("gear","Settings","Security, notifications, theme")+lrow("help","Help and support")+lrow("out","Sign out")+'<div class="sub" style="text-align:center;margin-top:14px">Crestline 1.1.0</div>',"padding-bottom:90px"),"acc"))
E.append(phone("E2 · FUNDS & LEDGER", top("Funds")+pad(card('<div class="sub">Available to trade</div><div class="num" style="font-size:32px;margin:2px 0 6px">₹52,310.40</div><div class="sub">Cash ₹44,200.00 · Pledged margin ₹8,110.40</div>')+'<div style="display:flex;gap:12px;margin:14px 0"><div class="btn lime" style="flex:1;height:48px">+ Add money</div><div class="btn ghost" style="flex:1;height:48px">Withdraw</div></div><div class="lbl" style="margin:6px 0 4px">RECENT</div>'+''.join(f'<div class="row" style="padding:13px 0;border-top:1px solid var(--line)"><div><b style="font-size:14.5px">{t}</b><div class="sub">{d}</div></div><b class="num {c}">{a}</b></div>' for t,d,c,a in [("Added via UPI","14 Oct","up","+₹25,000.00"),("Bought TCS · 12","12 Oct","dn","-₹40,920.00"),("Dividend · Reliance","08 Oct","up","+₹220.00"),("Withdrawal to HDFC","02 Oct","dn","-₹10,000.00")]))))
E.append(phone("E3 · WITHDRAW", top("Withdraw")+pad('<div class="sub" style="margin-top:6px">Amount</div><div class="num" style="font-size:44px;margin:4px 0 10px">₹ 10,000</div><div class="sub">Withdrawable now: <b class="num" style="color:var(--ink)">₹44,200.00</b></div><div style="display:flex;gap:8px;margin:14px 0">'+chip("₹5,000")+chip("₹10,000",True)+chip("Max")+'</div>'+card('<div class="row"><div style="display:flex;gap:12px;align-items:center"><span class="ico">'+ic("bank",20)+'</span><div><b>HDFC Bank ••••4567</b><div class="sub">Credited in 1 working day</div></div></div></div>')+'<div class="banner" style="background:var(--warnBg);color:var(--warn);margin-top:14px">Sale proceeds from today\'s trades can be withdrawn after settlement.</div>')+bottom(btn("Withdraw ₹10,000"))))
E.append(phone("E4 · REPORTS", top("Reports")+pad('<div class="seg" style="margin:6px 0 12px"><span class="on">Contract notes</span><span>Statements</span><span>Tax</span></div><div class="row" style="gap:8px;margin-bottom:6px">'+chip("October 2026",True)+chip("FY 2026-27")+'</div>'+''.join(f'<div class="row" style="padding:14px 0;border-top:1px solid var(--line)"><div style="display:flex;gap:12px;align-items:center"><span class="ico" style="width:40px;height:40px">{ic("doc",18)}</span><div><b style="font-size:14.5px">Contract note · {d}</b><div class="sub">{n} order{"" if n=="1" else "s"} · PDF</div></div></div><span style="font-weight:600;font-size:13px">Download</span></div>' for d,n in [("14 Oct 2026","1"),("12 Oct 2026","2"),("08 Oct 2026","1"),("02 Oct 2026","3")])+'<div class="banner" style="background:var(--limeD);color:var(--brandInk);margin-top:14px">Statements and tax reports are also sent to aarav.mehta@mail.com.</div>')))
E.append(phone("E5 · SETTINGS · SECURITY", top("Settings")+pad('<div class="lbl" style="margin:6px 0 2px">SECURITY</div>'+trow("Face ID","Unlock the app and confirm orders")+trow("Ask for PIN on every order","Extra check before each trade",False)+lrow("lock","Change PIN")+lrow("shield","Devices signed in","This phone + 1 more")+'<div class="lbl" style="margin:18px 0 2px">APP</div>'+trow("Price alerts and order updates","Push notifications")+trow("Dark theme","Match system",False)+'<div class="row" style="padding:14px 0;border-top:1px solid var(--line)"><b>Language</b><span class="mut">English ›</span></div>')))
E.append(phone("E6 · NOTIFICATIONS", top("Notifications")+pad('<div class="seg" style="margin:6px 0 12px"><span class="on">All</span><span>Orders</span><span>Alerts</span></div>'+''.join(f'<div class="row" style="padding:14px 0;border-top:1px solid var(--line);align-items:flex-start;gap:12px"><span class="ico" style="width:40px;height:40px;flex:0 0 auto;{"background:var(--limeD);border-color:var(--brandLine)" if n else ""}">{ic(i,18)}</span><div style="flex:1"><b style="font-size:14.5px">{t}</b><div class="sub" style="margin-top:2px;font-size:12.5px;line-height:1.4">{s}</div></div><span class="sub">{w}</span></div>' for i,t,s,w,n in [("trend","Order executed","Bought 22 Reliance at ₹1,209.73","2h",True),("bell","Alert hit: TCS","TCS fell to ₹3,300.00","5h",True),("doc","Contract note ready","For trades on 12 Oct","1d",False),("bank","Funds added","₹25,000 received via UPI","2d",False)]))))
E.append(phone("E7 · HELP & SUPPORT", top("Help")+pad('<div class="field" style="display:flex;gap:10px;align-items:center;padding:10px 14px">'+ic("search",18,"#8B9098")+'<span class="mut">Search help</span></div><div class="lbl" style="margin:8px 0 2px">TOP QUESTIONS</div>'+lrow("help","How long does a withdrawal take?")+lrow("help","Why was my order rejected?")+lrow("help","How do I pledge shares?")+lrow("help","How do I download a contract note?")+card('<div class="row"><div><b>Still stuck?</b><div class="sub" style="margin-top:2px">Chat with us · 9 am to 6 pm</div></div><span class="btn" style="height:42px;padding:0 18px;font-size:14px">Chat</span></div>','margin-top:16px')+'<div class="row" style="margin-top:14px;padding:0 4px"><span class="mut" style="font-size:13px">Call support</span><b class="num" style="font-size:13px">+91 22 6916 5100</b></div>')))
E.append(phone("E8 · EMPTY STATE", pad('<div class="row" style="height:52px"><div class="h1" style="font-size:26px">Orders</div></div><div class="seg" style="margin:6px 0 10px"><span class="on">Open</span><span>Executed</span><span>GTT</span></div><div style="text-align:center;margin-top:120px"><div style="width:84px;height:84px;margin:0 auto;border-radius:26px;background:#fff;border:1px solid var(--line);display:grid;place-items:center">'+ic("doc",34,"#8B9098")+'</div>'+h1("No open orders",22).replace('class="h1"','class="h1" style="margin-top:20px"')+'<div class="mut" style="margin:8px 28px 0;font-size:14px">Orders you place will show here until they are filled or the market closes.</div></div>')+'<div style="position:absolute;left:20px;right:20px;bottom:104px">'+btn("Explore stocks","lime")+'</div>',"ord"))
E.append(phone("E9 · NO INTERNET", pad('<div style="text-align:center;margin-top:150px"><div style="width:92px;height:92px;margin:0 auto;border-radius:50%;background:#fff;border:1px solid var(--line);display:grid;place-items:center">'+ic("wifi",40,"#8B9098")+'</div>'+h1("You\'re offline",24).replace('class="h1"','class="h1" style="margin-top:22px"')+'<div class="mut" style="margin:8px 26px 0;font-size:14px;line-height:1.5">Check your connection. Your orders and holdings are safe, and prices will refresh when you\'re back.</div></div>')+bottom(btn("Try again"),'<div class="sub" style="text-align:center">Last updated 2:14 PM</div>')))
sheet("flow-e-account-system.html","Crestline — account and system states",E)
